"""Additive codes C <= R^n over R = Z_q[i], stored as explicit bitmaps over R^n.

Every code is built by *enumerating its elements* (never from a size formula):
  * principal ideal  <alpha> = {alpha * r : r in R}           (Definition 4, n = 1)
  * R-submodule generated by vectors g_1..g_k                  (Remark 8, n > 1)
Membership is a bitmap lookup; sizes are popcounts.

Hermitian duals
---------------
Two definitions appear in the paper and they are implemented separately:
  * ``hermitian_dual``      : true orthogonal complement {y : <c, y>_H = 0 for all c in C}
                              (what Example 6/7 and Table 1 actually compute);
  * ``hermitian_dual_def6`` : the literal Definition 6, C^{perp_H} := <sigma(alpha)>.
``trace_dual`` is the complement w.r.t. Tr<.,.>_H, i.e. the condition that appears in the
commutation relation Z(v)X(u) = chi(<v,u>_H) X(u)Z(v)  (Definition 8).
"""
from __future__ import annotations

from dataclasses import dataclass, field

import numpy as np

from ..ring import GaussianRing


@dataclass
class AdditiveCode:
    ring: GaussianRing
    n: int
    mask: np.ndarray  # bool, length q^(2n)
    name: str = ""
    _gens: list | None = field(default=None, repr=False)

    # ------------------------------------------------------------ constructors
    @classmethod
    def from_indices(cls, ring, n, idx, name=""):
        mask = np.zeros(ring.size ** n, dtype=bool)
        mask[np.asarray(idx, dtype=np.int64)] = True
        return cls(ring, n, mask, name)

    @classmethod
    def principal(cls, ring: GaussianRing, alpha, name: str = "") -> "AdditiveCode":
        """<alpha> = {alpha * r : r in R}, enumerated over all r in R."""
        alpha = ring.reduce(alpha)
        prods = ring.mul(alpha[None, :], ring.elements())
        return cls.from_indices(ring, 1, ring.index(prods), name or f"<{ring.fmt(alpha)}>")

    @classmethod
    def submodule(cls, ring: GaussianRing, gens, name: str = "") -> "AdditiveCode":
        """R-submodule of R^n generated by the vectors in ``gens`` (shape (k, n, 2))."""
        gens = ring.reduce(np.asarray(gens))
        if gens.ndim == 2:
            gens = gens[None]
        n = gens.shape[1]
        i_unit = ring.elem(0, 1)
        add_gens = []
        for g in gens:  # R g = Z_q g + Z_q (i g)
            add_gens.append(g)
            add_gens.append(ring.mul(i_unit[None, :], g))
        return cls.zq_span(ring, n, add_gens, name)

    @classmethod
    def zq_span(cls, ring: GaussianRing, n: int, add_gens, name: str = "") -> "AdditiveCode":
        """Additive (Z_q-) span of the given vectors, by iterated closure."""
        cur = np.zeros((1, n, 2), dtype=np.int64)
        for h in add_gens:
            h = ring.reduce(np.asarray(h)).reshape(n, 2)
            ks = np.arange(ring.q, dtype=np.int64)
            mult = ring.scal(ks[:, None], h[None])  # (q, n, 2)
            allv = ring.add(cur[:, None], mult[None])  # (|cur|, q, n, 2)
            idx = np.unique(ring.vec_index(allv.reshape(-1, n, 2)))
            cur = ring.vec_from_index(idx, n)
        return cls.from_indices(ring, n, ring.vec_index(cur), name)

    # ------------------------------------------------------------ queries
    @property
    def size(self) -> int:
        return int(self.mask.sum())

    @property
    def indices(self) -> np.ndarray:
        return np.flatnonzero(self.mask)

    def vectors(self) -> np.ndarray:
        return self.ring.vec_from_index(self.indices, self.n)

    def contains(self, x) -> np.ndarray:
        x = np.asarray(x)
        if self.n == 1 and x.shape[-1] == 2 and (x.ndim == 1 or x.shape[-2] != 1):
            x = x[..., None, :]
        return self.mask[self.ring.vec_index(self.ring.reduce(x))]

    def issubset(self, other: "AdditiveCode") -> bool:
        return bool(np.all(other.mask[self.mask]))

    def __eq__(self, other) -> bool:  # type: ignore[override]
        return isinstance(other, AdditiveCode) and bool(np.array_equal(self.mask, other.mask))

    def is_additive_group(self) -> bool:
        """Closure under +, by brute force on all pairs when small, else on generators."""
        v = self.vectors()
        if len(v) ** 2 <= 4_000_000:
            s = self.ring.add(v[:, None], v[None, :]).reshape(-1, self.n, 2)
            return bool(self.contains(s).all())
        g = np.asarray(self.additive_generators())
        s = self.ring.add(v[:, None], g[None, :]).reshape(-1, self.n, 2)
        return bool(self.contains(s).all())

    def is_R_module(self, exhaustive_limit: int = 50_000_000) -> bool:
        """Closure under multiplication by every r in R.

        Exhaustive over all r in R when |R| * |C| <= exhaustive_limit; otherwise uses the
        equivalent criterion "additive subgroup and closed under x -> i x" (R = Z_q + Z_q i).
        """
        v = self.vectors()
        if self.ring.size * len(v) <= exhaustive_limit:
            for r in self.ring.elements():
                if not self.contains(self.ring.mul(r[None, None, :], v)).all():
                    return False
            return True
        i_unit = self.ring.elem(0, 1)
        return self.is_additive_group() and bool(
            self.contains(self.ring.mul(i_unit[None, None, :], v)).all()
        )

    def additive_generators(self) -> list[np.ndarray]:
        """A (greedy, small) Z_q-generating set of C, verified to span C."""
        if self._gens is not None:
            return self._gens
        gens: list[np.ndarray] = []
        span = AdditiveCode.zq_span(self.ring, self.n, [])
        # candidate order: R-module style generators first is not known here; scan by index
        for idx in self.indices:
            if span.mask[idx]:
                continue
            g = self.ring.vec_from_index(idx, self.n)
            gens.append(g)
            span = AdditiveCode.zq_span(self.ring, self.n, gens)
            if span.size == self.size:
                break
        assert span == self, "greedy additive generators failed to span the code"
        self._gens = gens
        return gens


# ---------------------------------------------------------------------- duals
def _complement(code: AdditiveCode, form: str, name: str) -> AdditiveCode:
    ring, n = code.ring, code.n
    Y = ring.all_vectors(n)  # (q^(2n), n, 2)
    ok = np.ones(len(Y), dtype=bool)
    for g in code.additive_generators():
        if form == "euclidean":
            val = np.mod(ring.mul(g[None], Y).sum(axis=-2), ring.q)  # sum_j g_j y_j
        elif form == "trace_left":
            val = ring.hermitian(Y, g[None])  # <y, g>_H  (y in the FIRST slot)
        else:
            val = ring.hermitian(g[None], Y)  # <g, y>_H, shape (q^(2n), 2)
        if form in ("hermitian", "euclidean"):
            ok &= ring.is_zero(val)
        elif form in ("trace", "trace_left"):
            ok &= ring.trace(val) == 0
        else:
            raise ValueError(form)
    return AdditiveCode(ring, n, ok, name)


def euclidean_dual(code: AdditiveCode) -> AdditiveCode:
    """{y : sum_j c_j y_j = 0 for all c in C}  (no conjugation) - for comparison only."""
    return _complement(code, "euclidean", f"{code.name}^perpE")


def hermitian_dual(code: AdditiveCode) -> AdditiveCode:
    """C^{perp_H} = {y in R^n : <c, y>_H = 0 for all c in C}.

    It suffices to test additive generators because <., y>_H is Z_q-linear in the first slot;
    ``orthogonal_exhaustive`` re-checks against all elements for small codes.
    """
    return _complement(code, "hermitian", f"{code.name}^perpH")


def trace_dual(code: AdditiveCode, side: str = "left") -> AdditiveCode:
    """Trace dual w.r.t. the commutation pairing of Definition 8.

    side="left"  (default): {v : Tr<v, c>_H = 0 for all c in C}  -- Z(v) commutes with every X(c),
                            and {x : Tr<v,x>_H = 0 for all v} = C  (the dual needed in Theorem 4);
    side="right"          : {y : Tr<c, y>_H = 0 for all c in C}.
    For R-submodules both equal the Hermitian dual.  For general additive codes they differ when
    Tr o sigma != Tr - true for the paper's Tr(a + bi) = a + b, since Tr(a - bi) = a - b."""
    if side not in ("left", "right"):
        raise ValueError(side)
    return _complement(code, "trace_left" if side == "left" else "trace", f"{code.name}^perpTr{side[0]}")


def hermitian_dual_closed_form(ring: GaussianRing, alpha) -> AdditiveCode:
    """C^{perp_H} for C = <alpha> (n = 1) in closed form:
        C^{perp_H} = Ann(sigma(alpha)) = sigma(Ann(alpha)) = < sigma(q / delta) >,  delta = gcd(alpha, q) in Z[i].
    Built by enumerating the principal ideal of the closed-form generator (no annihilator search);
    tests compare it with the enumerated orthogonal complement."""
    from ..ring import zi

    a = tuple(int(t) for t in ring.reduce(alpha))
    q = ring.q
    delta = zi.gcd(a, (q, 0)) if a != (0, 0) else (q, 0)
    num = zi.mul((q, 0), zi.conj(delta))
    n = zi.norm(delta)
    assert num[0] % n == 0 and num[1] % n == 0, "delta must divide q"
    q_over_delta = (num[0] // n, num[1] // n)
    gen = ring.conj(ring.reduce(np.array(q_over_delta)))
    return AdditiveCode.principal(ring, gen, f"<sigma(q/gcd({ring.fmt(ring.reduce(alpha))},q))>")


def hermitian_dual_def6(ring: GaussianRing, alpha) -> AdditiveCode:
    """Literal Definition 6 of the paper: C^{perp_H} := <sigma(alpha)> for C = <alpha>."""
    return AdditiveCode.principal(ring, ring.conj(ring.reduce(alpha)), f"<sigma({ring.fmt(alpha)})>")


def orthogonal_exhaustive(A: AdditiveCode, B: AdditiveCode, chunk: int = 2_000_000) -> bool:
    """True iff <a, b>_H = 0 for *every* pair (a, b) in A x B (no generator shortcut)."""
    ring = A.ring
    va, vb = A.vectors(), B.vectors()
    step = max(1, chunk // max(1, len(vb)))
    for s in range(0, len(va), step):
        val = ring.hermitian(va[s : s + step, None], vb[None, :])
        if not ring.is_zero(val).all():
            return False
    return True
